fn correct_of(qi: i32) -> i32 {
    match qi {
        0 => 0,
        1 => 1,
        _ => 0,
    }
}

fn draw_question(qi: i32) {
    if qi == 0 {
        host::display::draw_string(76, 80, "2 + 2 * 2 = ?", 0xffffff, 2);
    } else if qi == 1 {
        host::display::draw_string(76, 80, "BITS IN ONE BYTE?", 0xffffff, 2);
    } else {
        host::display::draw_string(76, 80, "HEX FF IN DECIMAL?", 0xffffff, 2);
    }
}

fn draw_answer(qi: i32, a: i32, x: i32, y: i32) {
    if qi == 0 {
        if a == 0 {
            host::display::draw_string(x, y, "6", 0xffffff, 2);
        } else if a == 1 {
            host::display::draw_string(x, y, "8", 0xffffff, 2);
        } else {
            host::display::draw_string(x, y, "4", 0xffffff, 2);
        }
    } else if qi == 1 {
        if a == 0 {
            host::display::draw_string(x, y, "4", 0xffffff, 2);
        } else if a == 1 {
            host::display::draw_string(x, y, "8", 0xffffff, 2);
        } else {
            host::display::draw_string(x, y, "16", 0xffffff, 2);
        }
    } else {
        if a == 0 {
            host::display::draw_string(x, y, "255", 0xffffff, 2);
        } else if a == 1 {
            host::display::draw_string(x, y, "256", 0xffffff, 2);
        } else {
            host::display::draw_string(x, y, "128", 0xffffff, 2);
        }
    }
}

fn frame(t: i32) {
    host::display::clear(0x0e1013);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }
    let qi: i32 = host::display::state_get(1);
    let score: i32 = host::display::state_get(2);

    if host::display::state_get(3) == 1 {
        host::display::draw_string(150, 140, "QUIZ OVER", 0xffffff, 3);
        host::display::draw_number(210, 220, score, 0x66ddff, 5);
        host::display::draw_string(260, 236, "OF 3", 0x8899aa, 2);
        if score == 3 {
            host::display::draw_string(180, 320, "PERFECT RUN", 0x33ff88, 2);
        } else if score >= 2 {
            host::display::draw_string(190, 320, "NOT BAD", 0xffcc33, 2);
        } else {
            host::display::draw_string(170, 320, "STUDY UP", 0xbb5533, 2);
        }
        host::display::draw_string(160, 420, "TAP TO RESTART", 0x556677, 1);
        if click == 1 {
            host::display::state_set(1, 0);
            host::display::state_set(2, 0);
            host::display::state_set(3, 0);
        }
    } else {
        host::display::draw_string(76, 30, "QUESTION", 0x556677, 1);
        host::display::draw_number(152, 28, qi + 1, 0xffffff, 1);
        host::display::draw_string(170, 30, "OF 3", 0x556677, 1);
        draw_question(qi);
        let mut a: i32 = 0;
        while a < 3 {
            let y: i32 = 160 + a * 90;
            host::display::fill_rect(76, y, 360, 64, 0x1c212b);
            draw_answer(qi, a, 100, y + 22);
            a = a + 1;
        }
        let flash: i32 = host::display::state_get(4);
        if flash > 0 {
            if host::display::state_get(5) == 1 {
                host::display::draw_string(76, 450, "CORRECT", 0x33ff88, 2);
            } else {
                host::display::draw_string(76, 450, "WRONG", 0xbb3333, 2);
            }
            host::display::state_set(4, flash - 1);
        }
        if click == 1 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= 76 && px < 436 && py >= 160 && py < 430 {
                let pick: i32 = (py - 160) / 90;
                if pick < 3 && (py - 160) % 90 < 64 {
                    if pick == correct_of(qi) {
                        host::display::state_set(2, score + 1);
                        host::display::state_set(5, 1);
                    } else {
                        host::display::state_set(5, 0);
                    }
                    host::display::state_set(4, 30);
                    if qi >= 2 {
                        host::display::state_set(3, 1);
                    } else {
                        host::display::state_set(1, qi + 1);
                    }
                }
            }
        }
    }
    host::display::present();
}
